    static void openSettings(Minecraft mc){NativeRtsController.toggle();mc.setScreen(new GeneralsSetupScreen(null));click(mc,"Мир и взаимодействия");}
    static void spawn(NativeWorldView v,String type,Vec3 point)throws Exception{var p=v.origin.nativePoint(point);v.session.send("TEST_SPAWN "+type+" "+p.x+" "+p.y+" "+p.z);}
    static void fire(NativeWorldView v)throws Exception{var p=v.origin.nativePoint(new Vec3(-10.5,64.2,.5));v.session.send("TEST_FIRE "+tank+" "+p.x+" "+p.y+" "+p.z);}
    static int countDirt(Minecraft mc){var l=mc.getSingleplayerServer().getLevel(GeneralsMod.ARENA);int n=0;for(int x=-12;x<=-8;x++)for(int z=-2;z<=2;z++)for(int y=60;y<=64;y++)if(l.getBlockState(new BlockPos(x,y,z)).is(Blocks.DIRT)||l.getBlockState(new BlockPos(x,y,z)).is(Blocks.GRASS_BLOCK))n++;return n;}
    static void finish(Minecraft mc,String result,String error){done=true;try{var report=new LinkedHashMap<String,Object>();report.put("result",result);report.put("checks",checks);report.put("stage",stage);report.put("root",String.valueOf(root));report.put("world",world);report.put("nativeBundled",NativeRuntime.bundled());if(NativeWorldView.current!=null)report.put("session",NativeWorldView.current.session.directory.toString());if(error!=null)report.put("error",error);Path out=Path.of(System.getProperty("generalsmc.evidence","evidence"));Files.createDirectories(out);Files.writeString(out.resolve(Boolean.getBoolean("generalsmc.feedbackRegression")?"native-version-tests.json":Boolean.getBoolean("generalsmc.releaseUxOnly")?"release-details-tests.json":Boolean.getBoolean("generalsmc.networkPolishOnly")?"network-polish-ux-tests.json":Boolean.getBoolean("generalsmc.octoberOnly")?"october-ux-tests.json":Boolean.getBoolean("generalsmc.recoveryOnly")?"recovery-ux-tests.json":"release-ux-tests.json"),GeneralsMod.JSON.toJson(report));}catch(Exception e){GeneralsMod.LOG.error("Release evidence failed",e);}NativeRtsController.stop();mc.stop();}
